import{z as i,x as s,o as t,c as d,q as B,j as l,D as E,d as r,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"希腊字母的组合管理","description":"","frontmatter":{"title":"希腊字母的组合管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-greeks-portfolio.md","filePath":"quant/vt-greeks-portfolio.md","lastUpdated":1791413859000}'),p={name:"quant/vt-greeks-portfolio.md"};function m(h,a,D,g,u,C){const A=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="希腊字母的组合管理" tabindex="-1">希腊字母的组合管理 <a class="header-anchor" href="#希腊字母的组合管理" aria-label="Permalink to &quot;希腊字母的组合管理&quot;">​</a></h1><div class="epigraph"><p>单一头寸的希腊字母是物理量，组合的希腊字母是政策：加总方式、情景网格与残差预算，共同决定你真正持有什么。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives；聚合口径据期权账簿实务整理</footer></div><p><a href="/quant/vt-variance-swap-deep">上一课</a>把方差互换的持有期账拆成 carry、delta、期限与残差四栏；单一产品可以手算，多产品组合必须靠聚合。基础课给了单工具的 <a href="/quant/greeks-hedge">Delta / Gamma / Vega 对冲</a>、<a href="/quant/higher-greeks">Charm / Color 高阶希腊</a>与<a href="/quant/delta-hedge-freq">对冲频率</a>；做市课给了账本与限额的流程。本课写波动率交易组合本身：怎么聚合、怎么决策、留什么残差——把账本上的残余收敛成策略观点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>总 Vega 一个数会撒谎：一万三十天 Vega 与一万两年 Vega 相加成两万，但波动跳一个点时两者的盈亏差好几倍——期限结构被加总抹掉了。Vanna 与 Charm 让现货不动的隔夜头寸也在走。对冲还有成本与工具约束：Gamma 与 Vega 通常不能被单一工具同时清零，每个「清零」动作都在买入另一维度的暴露。不做组合管理，账本就同时持有一堆没人要过的观点，在压力日一起兑现。</p><p><span class="marginnote">术语翻译：Vega 是「波动动一个单位，组合赚亏多少」；Vanna 是波动与现货一起动时的交叉项；Charm 是希腊字母自己随时间溜走的速度。三者合计意味着：现货不动、波动不动的隔夜，账本仍在漂。</span></p><h3 id="三步走" tabindex="-1">三步走 <a class="header-anchor" href="#三步走" aria-label="Permalink to &quot;三步走&quot;">​</a></h3><p>第一步聚合：按到期桶与分位桶分列，桶内 Vega 加权、桶间不平均加总。做市课的<a href="/quant/omm-vol-position-ledger">波动率仓位的账本</a>给了字段口径：每手的成交隐波与标记隐波、Vega 的期限与分位归属——交易组合直接沿用，别另造一套记号。</p><p>第二步情景：把各阶希腊折进统一的情景网格——平行 Vega、偏度加陡、日历变平、现货跳水配波动跳升。<a href="/quant/omm-greeks-limits">敏感度 limits 与聚合</a>的四层限额给出分级：先聚仓位再算损失，跨标的保留相关性趋一的压力限额。</p><p>第三步决策分层：Delta 走规则，带宽由 <a href="/quant/gamma-theta-tradeoff">gamma-theta 权衡</a>与<a href="/quant/discrete-hedge-error">离散对冲误差</a>定，不逐日裁量；Vega 按观点对冲，用最流动的期限做工具；Vanna 与 Charm 的隔夜漂移按做市课的<a href="/quant/omm-vanna-charm-daily">每日排班</a>预留偏移；高阶残差进「已知持有」清单，写明理由与止损线。</p><p><span class="marginnote">一个实用的验收问句：挑出组合里最大的一笔 Vega 桶，问「这是策略还是对冲副产品」。答不出策略名的桶，多半是某次对冲或调仓留下的化石——化石不会立刻咬人，但会在体制切换日集体醒来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>组合管理的目标是<strong>让残差就是观点</strong>。建仓时主动构造：想留偏度暴露，就用 <a href="/quant/vanna-volga">Vanna / Volga 三点</a>把平行 Vega 抽掉；想留期限结构暴露，就用远月对近月的 Vega 配比把整体 Vega 净平。做完这些，账本上的残余与策略论点一一对应，限额讨论的从「这个数字怎么来的」变成「这个观点该多大」——后者才是投资决策，前者只是对账。</p><p><span class="marginnote">直觉类比：好的组合像一张点好的菜——端上来的每道都是你点的（观点）；差的组合像一桌流水菜，问起来路全是「厨师顺手加的」（对冲副产品）。晨会该讨论的是「这观点该多大」，而不是「这数字哪来的」。</span></p>',14)),(t(),l(o,null,{default:E(()=>[n(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20POS%5B%22%E5%85%A8%E9%87%8F%E6%8C%81%E4%BB%93%22%5D%20--%3E%20BUCK%5B%22%E6%A1%B6%E8%81%9A%E5%90%88%EF%BC%9A%E6%9C%9F%E9%99%90%E4%B8%8E%E5%88%86%E4%BD%8D%22%5D%0A%20%20BUCK%20--%3E%20GRID%5B%22%E6%83%85%E6%99%AF%E7%BD%91%E6%A0%BC%E6%8A%98%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20GRID%20--%3E%20DEC%7B%22%E5%86%B3%E7%AD%96%E5%88%86%E5%B1%82%22%7D%0A%20%20DEC%20--%3E%7C%22Delta%22%7C%20RULE%5B%22%E8%A7%84%E5%88%99%E5%8C%96%E5%B8%A6%E5%AE%BD%E5%AF%B9%E5%86%B2%22%5D%0A%20%20DEC%20--%3E%7C%22Vega%22%7C%20VIEW%5B%22%E6%8C%89%E8%A7%82%E7%82%B9%E9%80%89%E5%B7%A5%E5%85%B7%22%5D%0A%20%20DEC%20--%3E%7C%22%E9%AB%98%E9%98%B6%22%7C%20HOLD%5B%22%E5%B7%B2%E7%9F%A5%E6%8C%81%E6%9C%89%E6%B8%85%E5%8D%95%22%5D%0A%20%20RULE%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E8%B4%A6%E4%B8%8E%E6%99%A8%E4%BC%9A%22%5D%0A%20%20VIEW%20--%3E%20RES%0A%20%20HOLD%20--%3E%20RES%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"为什么情景网格先于单点希腊：希腊字母是局部导数，组合的价值函数在偏度与日历维度上高度非线性，单点数在「波动跳三个点」的情景下没有信息量。折成情景损失后，不同到期、不同执行、不同标的的头寸才落在同一把尺子上，限额也因此可比。",-1)),a[5]||(a[5]=e("p",null,"为什么 Delta 必须规则化：Delta 对冲是无观点的执行动作，逐日裁量会把执行台变成隐性策略台，事后无法归因。规则的成本是放弃小幅优化，换来的是每笔对冲都有据可查——这与第一课「数字从哪来」的口径同源。",-1)),(t(),l(o,null,{default:E(()=>[n(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E4%B8%A4%E6%9C%AC%E8%B4%A6%3A%E6%80%BB%20Vega%20%E9%83%BD%E6%98%AF%E4%B8%A4%E4%B8%87%22%5D%20--%3E%20A%5B%22%E8%B4%A6%E6%9C%ACA%3A%E5%85%A8%E6%8A%BC%E4%B8%A4%E5%B9%B4%E6%9C%9F%E6%A1%B6%22%5D%0A%20%20SAME%20--%3E%20B%5B%22%E8%B4%A6%E6%9C%ACB%3A%E5%85%A8%E6%8A%BC%E4%B8%89%E5%8D%81%E5%A4%A9%E6%A1%B6%22%5D%0A%20%20A%20--%3E%20MOVE%5B%22%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%E9%9D%9E%E5%B9%B3%E8%A1%8C%3A%E7%9F%AD%E7%AB%AF%E8%B7%B3%E4%B8%89%E4%B8%AA%E7%82%B9%2C%E9%95%BF%E7%AB%AF%E5%8F%AA%E5%8A%A8%E5%8D%8A%E4%B8%AA%22%5D%0A%20%20B%20--%3E%20MOVE%0A%20%20MOVE%20--%3E%20PA%5B%22A%20%E7%9B%88%E4%BA%8F%E6%9C%89%E9%99%90%3A%E9%95%BF%E7%AB%AF%E5%87%A0%E4%B9%8E%E6%B2%A1%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20PB%5B%22B%20%E9%87%8D%E5%88%9B%3A%E7%9F%AD%E7%AB%AF%E6%81%B0%E6%98%AF%E5%AE%83%E7%9A%84%E5%85%A8%E9%83%A8%22%5D%0A%20%20PA%20--%3E%20LESS%5B%22%E5%8A%A0%E6%80%BB%E5%90%8E%E7%9A%84%E3%80%8C%E6%80%BB%20Vega%20%E4%B8%A4%E4%B8%87%E3%80%8D%E6%8A%B9%E6%8E%89%E4%BA%86%E8%BF%99%E4%BB%BD%E5%B7%AE%E5%88%AB%22%5D%0A%20%20PB%20--%3E%20LESS%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲单工具对冲的推导；跨标的相关的压力情景归限额层，本课只消费；跨币种头寸的折算与准入摩擦留给跨市场那课。组合优化的解析解（如方差互换堆的解析 delta）不展开，数值情景已够日常决策。最后一句话作为下一单元的门：残差收敛成观点之后，观点本身值不值得持有——这是「策略与风控」单元要用案例回答的问题。</p><p><span class="marginnote">常见误区：初学者以为把希腊全清零就万事大吉。其实每个「清零」动作都在用另一个工具买进另一维度的暴露——Gamma 与 Vega 常常无法同时清零；清零报表越干净，越要问风险被藏进了哪个桶。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总 Vega 会撒谎：先按到期与分位分桶，桶间不做平均加总。</li><li>情景网格先于单点希腊：不同头寸折成情景损失才可比、可限额。</li><li>决策分三层：Delta 规则化、Vega 按观点、高阶残差进已知持有清单。</li><li>组合管理的目标是「残差即观点」：建仓时净掉不想要的暴露。</li><li>化石桶是隐性风险：答不出策略名的暴露会在体制切换日集体醒来。</li><li>出处：Hull, <em>Options, Futures, and Other Derivatives</em>；账本与限额口径沿做市课字段整理。</li></ul>',5))])}const q=i(p,[["render",m]]);export{V as __pageData,q as default};
